from taf.ul.ettf.events.notifier import Notifier
from taf.ul.ettf.scheduler.base_listeners import SuiteListener


class EventsGroupOpener(SuiteListener):

    def start_suite(self, suite, result):
        Notifier().open_group(EventsGroupOpener._get_suite_unique_name(suite))

    def start_test(self, test, result):
        Notifier().open_group(EventsGroupOpener._get_test_unique_name(test))

    @staticmethod
    def _get_suite_unique_name(suite):
        return suite.name

    @staticmethod
    def _get_test_unique_name(test):
        return test.parent.name + '.' + test.name


events_group_opener = EventsGroupOpener
